// Package generated holds the backend configuration struct generated by
// go-jsonschema from the vendored config schema (config.go, regenerated via
// `make generate-config`), plus a hand-written stable alias (this file). It is
// read-only generated code — never hand-edit config.go; change the AppConfig
// model and regenerate (impl/6.0 §2).
package generated

// BackendConfig is the stable name the installer/binder/doctor refer to for the
// generated backend configuration root (impl/6.0 §2). go-jsonschema derives the
// root type name from the schema file (config-schema.json → ConfigSchemaJson);
// this alias pins the name the rest of the CLI uses so a future generator quirk
// or filename change can't ripple through internal/cli/ctl. It is a type ALIAS
// (not a defined type), so BackendConfig and ConfigSchemaJson are identical for
// reflection, JSON, and method-set purposes — the binder walks either interchangeably.
//
// This file is hand-written and lives beside the generated config.go precisely so
// the generator never overwrites it.
type BackendConfig = ConfigSchemaJson
